import time

def throttle_messages(limit, window):
    count = 0
    start = time.time()

    while count < limit:
        next_message = yield
        count += 1

        end = time.time()
        if (end - start) > window: 
            count = 0
            start = end

    yield

def fibonacci_generator(n):
    a, b = 0, 1
    while a < 2 * n - 1:
        yield a
        a, b = b, a + b

def binary_search(arr, x): 
    l = 0
    r = len(arr) - 1

    while l <= r: 
        mid = l + (r - l) // 2
        if arr[mid] == x: 
            return mid 
        elif arr[mid] < x: 
            l = mid + 1
        else: 
            r = mid - 1

    return -1

def maxSubArraySum(arr):
