import re
import requests

urls = set()

def get_urls(url):
    website = requests.get(url)
    content = website.text
    links = re.findall(r'<a .*?href=[\'"](.*?)[\'"].*?>', content)

    for i in links:
        if i.startswith("/"):
            base_url = url
            i = base_url + i
            if i in urls:
                continue
            urls.add(i)
            get_urls(i)
        elif url in i:
            if i in urls:
                continue
            urls.add(i)
            get_urls(i)

if __name__ == "__main__":
    get_urls("https://www.example.com")
    for i in urls:
        print(i)

# Define a StateMachine class
class StateMachine: 
    def __init__(self): 
        self.handlers = {} 
        self.startState = None
        self.endStates = [] 

    def add_state(self, state): 
        self.handlers[state.name] = state

    def set_start(self, name): 
        self.startState = name

    def set_end(self, name): 
        self.endStates.append(name) 

    def run(self): 
        try: 
            handler = self.handlers[self.startState] 
        except: 
            raise(Exception, "Must call .set_start() before .run()")
        while True:
            # Get the next keyboard event
            event = get_event()
            if event:
                newState = handler.run(event) 
            if newState.name in self.endStates: 
                break 
            else: 
                handler = self.handlers[newState.name]

