def print_sorted_list(list1, list2): 
    result = [] 
    while list1 and list2: 
        if list1.value > list2.value: 
            result.append(list2.value) 
            list2 = list2.next 
        else: 
            result.append(list1.value) 
            list1 = list1.next 
    if list1: 
        result.extend(list1) 
    if list2: 
        result.extend(list2) 
    return result

