def median(x,y,z,w):
    nums = [x,y,z,w]
    nums.sort()
    mid =len(nums)//2
    if len(nums)%2 == 0:
        median = (nums[mid] + nums[mid-1])/2
    else:
        median = nums[mid]
    return median

