def all_combinations(nums):
  result = [[]]
  for num in nums:
    temp_result = []
    for res in result:
      temp_result.append(res + [num])
    result.extend(temp_result)
  return result

print(all_combinations(nums)) # [[1], [2], [3], [1, 2], [1, 3], [2, 3], [1, 2, 3]]

# Using a hash table, construct a program to find all of the pairs of an array whose sum is equal to a given target

def find_pairs(arr, target):
    seen = {}
    pairs = []
    for num in arr:
        if target-num in seen:
            pairs.append((num, target-num))
        seen[num] = True
    return pairs

print(find_pairs(arr, target)) # [(2, 6), (1, 7)]

